const categories=['Personal Care','Baby','Cleaning','Household'];
let cart=JSON.parse(localStorage.getItem('kwa60-cart')||'{}'),category='All',query='',driverOnline=false,driverOrder='available',driverChecks={},driverDeliveries=0,driverEarnings=0;
let savedProfile=JSON.parse(localStorage.getItem('kwa60-profile')||'{}'),savedLocation=JSON.parse(localStorage.getItem('kwa60-location')||'{}');
const $=s=>document.querySelector(s),fmt=n=>'R'+Number(n).toFixed(2),count=()=>Object.values(cart).reduce((a,b)=>a+b,0),subtotal=()=>products.reduce((a,p)=>a+(p.price||0)*(cart[p.id]||0),0);
const productPrice=p=>p.price===169?'R169':fmt(p.price);
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function card(p){return `<article class="product-card" data-open-product="${p.id}" tabindex="0" role="button" aria-label="View ${p.name} details"><div class="product-img"><img loading="lazy" src="assets/cropped/${p.image}" alt="${p.name}" onerror="this.remove()"></div><div class="product-info"><div class="product-name">${p.name}</div><div class="product-detail">${p.detail}</div><div class="product-action-row"><div class="product-price">${p.price==null?'Ask in store':productPrice(p)}</div><button class="add" data-add="${p.id}" aria-label="Add ${p.name}">Add</button></div></div></article>`}
function renderHome(){const aisleIcons={'Personal Care':'🧴','Baby':'🍼','Cleaning':'🧹','Household':'🏠'};$('#aisles').innerHTML=categories.map(c=>`<button class="aisle" data-category="${c}"><i>${aisleIcons[c]}</i>${c}</button>`).join('');$('#bestsellers').innerHTML=products.filter(p=>p.price!==null).map(card).join('');$('#personal').innerHTML=products.filter(p=>['Baby','Personal Care'].includes(p.category)).map(card).join('')}
function renderProducts(){const items=products.filter(p=>(category==='All'||p.category===category)&&p.name.toLowerCase().includes(query.toLowerCase()));$('#product-grid').innerHTML=items.map(card).join('');$('#listing-title').textContent=query?'Search results':category==='All'?'All products':category;$('#product-count').textContent=`${items.length} ${items.length===1?'product':'products'}`;$('#category-list').innerHTML=[['All','✳'],...categories.map(c=>[c,({'Personal Care':'✦','Baby':'♡','Cleaning':'⌂','Household':'▣'})[c]])].map(([c,icon])=>`<button class="category-chip ${category===c?'category-chip-active':''}" data-category="${c}" aria-pressed="${category===c}"><span>${icon}</span>${c}</button>`).join('');$('#back-categories').classList.toggle('hidden',category==='All'&&!query)}
function renderCart(){let items=products.filter(p=>cart[p.id]);$('#nav-count').textContent=count();$('#nav-count').classList.toggle('hidden',count()===0);$('#empty-cart').classList.toggle('hidden',items.length>0);$('#cart-content').classList.toggle('hidden',items.length===0);$('#cart-items').innerHTML=items.map(p=>`<div class="cart-row"><img class="cart-thumb" src="assets/cropped/${p.image}" onerror="this.style.visibility='hidden'"><div class="cart-desc"><b>${p.name}</b><small>${productPrice(p)} each</small><div class="quantity"><button data-change="-1" data-id="${p.id}">−</button><span>${cart[p.id]}</span><button data-change="1" data-id="${p.id}">+</button></div></div><b>${fmt(p.price*cart[p.id])}</b></div>`).join('');$('#subtotal').textContent=fmt(subtotal());$('#cart-guidance').textContent=subtotal()>=100?'YOUR ORDER QUALIFIES FOR DELIVERY':'ADD MORE ITEMS TO YOUR CART';$('#checkout').disabled=subtotal()<100}
function save(){localStorage.setItem('kwa60-cart',JSON.stringify(cart));renderCart()}
function nav(name){document.querySelectorAll('.screen').forEach(e=>e.classList.remove('active'));const target=$(`#screen-${name.toLowerCase()}`);if(target)target.classList.add('active');document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('selected',e.dataset.nav===name));if(name==='Products'){$('#product-search').value=query;renderProducts()}if(name==='Cart')renderCart();if(name==='Orders')renderCustomerTracking();history.replaceState(null,'',`#${name.toLowerCase()}`)}
function setCategory(c){category=c;nav('Products');renderProducts();$('#screen-products').scrollTop=0}
let bubbleTimer,driverLocationWatch=null;
function showPriceBubble(price){$('#bubble-price').textContent=price===169?'R169':fmt(price);const b=$('#price-bubble');b.classList.add('show');clearTimeout(bubbleTimer);bubbleTimer=setTimeout(()=>b.classList.remove('show'),1900)}
function openProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('#detail-name').textContent=p.name;$('#detail-description').textContent=p.detail;$('#detail-price').textContent=p.price==null?'Ask in store':productPrice(p);$('#detail-image').src=`assets/cropped/${p.image}`;$('#detail-image').alt=p.name;$('#detail-add').dataset.add=p.id;$('#detail-add').disabled=p.price==null;$('#detail-add').textContent=p.price==null?'Price unavailable':'Add to cart';$('#product-overlay').classList.add('open');$('#product-overlay').setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}
function closeProduct(){const m=$('#product-overlay');m.classList.remove('open');m.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function add(id){const p=products.find(x=>x.id===id);if(p.price==null){toast('Please confirm this item’s price in store');return}cart[id]=(cart[id]||0)+1;save();showPriceBubble(p.price)}
function renderDriver(){const status=$('#driver-status'),note=$('#driver-status-note'),toggle=$('#driver-toggle'),orders=$('#driver-orders');if(!status)return;status.textContent=driverOnline?'You’re online':'You’re offline';note.textContent=driverOnline?'You’re visible for nearby Kwamakhi deliveries.':'Go online when you’re ready for deliveries.';toggle.textContent=driverOnline?'Go offline':'Go online';toggle.classList.toggle('is-online',driverOnline);$('#driver-delivery-count').textContent=driverDeliveries;$('#driver-earnings').textContent='R'+driverEarnings.toFixed(2);$('#driver-order-count').textContent=driverOnline&&driverOrder==='available'?'1 available':driverOrder==='accepted'?'1 active':'0 available';if(!driverOnline){orders.innerHTML='<div class="driver-empty"><span>⌖</span><b>Ready when you are</b><p>Go online to see delivery requests near Kwamakhi Store.</p></div>';return}if(driverOrder==='available'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">NEW REQUEST · #KW60-014</span><span class="driver-order-time">12 min</span></div><div class="driver-route"><span class="route-dot pickup"></span><div><small>PICK UP</small><b>Kwamakhi Store</b></div></div><div class="driver-route"><span class="route-dot dropoff"></span><div><small>DELIVER TO</small><b>14 Nomonde Street, Village</b></div></div><div class="driver-order-items"><b>2 items</b><span>Village loaf · Full cream milk</span></div><div class="driver-order-bottom"><span>Delivery pay <b>R28.00</b></span><button data-driver-action="accept">Accept order</button></div></article>';return}if(driverOrder==='accepted'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">IN PROGRESS · #KW60-014</span><span class="driver-order-time">12 min</span></div><div class="driver-route"><span class="route-dot pickup done"></span><div><small>PICK UP</small><b>Kwamakhi Store</b></div></div><div class="driver-route"><span class="route-dot dropoff"></span><div><small>DELIVER TO</small><b>14 Nomonde Street, Village</b></div></div><div class="driver-order-items"><b>2 items</b><span>Village loaf · Full cream milk</span></div><div class="driver-order-bottom"><span>Delivery pay <b>R28.00</b></span><button data-driver-action="complete">Mark delivered</button></div></article>';return}orders.innerHTML='<div class="driver-empty driver-complete"><span>✓</span><b>Delivery completed</b><p>Great work. Your R28.00 has been added to today’s earnings.</p></div>'}

function driverBasket(){return products.filter(p=>cart[p.id]).map(p=>({...p,quantity:cart[p.id]}))}
function renderDriver(){const status=$('#driver-status'),note=$('#driver-status-note'),toggle=$('#driver-toggle'),orders=$('#driver-orders');if(!status)return;status.textContent=driverOnline?'You’re online':'You’re offline';note.textContent=driverOnline?'You’re visible for nearby Kwamakhi deliveries.':'Go online when you’re ready for deliveries.';toggle.textContent=driverOnline?'Go offline':'Go online';toggle.classList.toggle('is-online',driverOnline);$('#driver-delivery-count').textContent=driverDeliveries;$('#driver-earnings').textContent='R'+driverEarnings.toFixed(2);const map=$('#driver-map-panel');map.classList.toggle('hidden',driverOrder!=='delivering');$('#driver-order-count').textContent=driverOnline&&driverOrder==='available'?'1 available':driverOrder==='picking'?'1 active':driverOrder==='paid'||driverOrder==='delivering'?'Out for delivery':'0 available';if(!driverOnline){orders.innerHTML='<div class="driver-empty"><span>⌖</span><b>Ready when you are</b><p>Go online to see delivery requests near Kwamakhi Store.</p></div>';return}const basket=driverBasket();if(driverOrder==='available'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">NEW REQUEST · #KW60-014</span><span class="driver-order-time">12 min</span></div><div class="driver-route"><span class="route-dot pickup"></span><div><small>PICK UP</small><b>Kwamakhi Store</b></div></div><div class="driver-route"><span class="route-dot dropoff"></span><div><small>DELIVER TO</small><b>'+((savedLocation.street||'14 Nomonde Street')+', '+(savedLocation.area||'Village'))+'</b></div></div><div class="driver-order-items"><b>Customer basket · '+basket.reduce((n,p)=>n+p.quantity,0)+' items</b><span>'+(basket.length?basket.map(p=>p.quantity+' × '+p.name).join(' · '):'Customer basket is empty on this device')+'</span></div><div class="driver-order-bottom"><span>Delivery pay <b>R28.00</b></span><button data-driver-action="accept">Accept &amp; view pick list</button></div></article>';return}if(driverOrder==='picking'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">PICK LIST · #KW60-014</span><span class="driver-order-time">'+basket.reduce((n,p)=>n+p.quantity,0)+' items</span></div><div class="driver-route"><span class="route-dot pickup"></span><div><small>COLLECT FROM</small><b>Kwamakhi Store</b></div></div><div class="driver-pick-list">'+(basket.length?basket.map(p=>'<label class="driver-pick-item"><input type="checkbox" data-pick-item="'+p.id+'" '+(driverChecks[p.id]?'checked':'')+'><span><b>'+p.name+'</b><small>'+p.detail+' · '+p.quantity+' × '+(p.price==null?'price to confirm':productPrice(p))+'</small></span><strong>'+(p.price==null?'Confirm price':fmt(p.price*p.quantity))+'</strong></label>').join(''):'<div class="driver-empty"><b>No groceries in the customer basket</b><p>Add items to the customer cart before testing this pick list.</p><button data-nav="Products">Browse products</button></div>')+'</div><div class="driver-payment-summary"><span>Store groceries <b>R'+subtotal().toFixed(2)+'</b></span><span>Driver delivery pay <b>R28.00</b></span><small>At the till, pay the grocery total with the Kwamakhi card. Delivery pay remains separate for the driver.</small></div><div class="driver-order-bottom"><span>'+(basket.length&&basket.every(p=>driverChecks[p.id]&&p.price!=null)?'All items checked · prices confirmed':basket.some(p=>p.price==null)?'Price needed for an exact till total':'Check each item picked')+'</span><button data-driver-action="paid" '+(!basket.length||!basket.every(p=>driverChecks[p.id]&&p.price!=null)?'disabled':'')+'>Confirm Kwamakhi card purchase</button></div></article>';return}if(driverOrder==='paid'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">PURCHASE RECORDED · #KW60-014</span><span class="driver-order-time">Ready to go</span></div><div class="driver-payment-summary"><span>Groceries paid with Kwamakhi card <b>R'+subtotal().toFixed(2)+'</b></span><span>Delivery pay stays with driver <b>R28.00</b></span><small>This preview records the till step only; no card is charged in this demo.</small></div><div class="driver-order-bottom"><span>Customer: '+(savedProfile.name||'Kwa60 customer')+'</span><button data-driver-action="start">Start delivery &amp; show map</button></div></article>';return}if(driverOrder==='delivering'){orders.innerHTML='<article class="driver-order-card"><div class="driver-order-top"><span class="driver-order-id">ON THE WAY · #KW60-014</span><span class="driver-order-time">Tracking preview</span></div><div class="driver-route"><span class="route-dot pickup done"></span><div><small>DELIVER TO</small><b>'+(savedLocation.street||'14 Nomonde Street')+', '+(savedLocation.area||'Village')+'</b></div></div><div class="driver-order-bottom"><span>Delivery pay <b>R28.00</b></span><button data-driver-action="complete">Mark delivered</button></div></article>';startDriverMap();return}orders.innerHTML='<div class="driver-empty driver-complete"><span>✓</span><b>Delivery completed</b><p>Great work. Your R28.00 has been added to today’s earnings.</p></div>'}
function renderCustomerTracking(){const box=$('#customer-tracking'),empty=$('#screen-orders .empty-state');if(!box)return;const live=driverOrder==='delivering',loc=JSON.parse(localStorage.getItem('kwa60-live-location')||'null');box.classList.toggle('hidden',!live);if(empty)empty.classList.toggle('hidden',live);if(live){$('#customer-track-status').textContent=loc?'Driver location updated just now.':'Waiting for driver location permission.';if(loc)$('#customer-track-map').src='https://www.openstreetmap.org/export/embed.html?bbox='+(loc.lon-.008)+'%2C'+(loc.lat-.008)+'%2C'+(loc.lon+.008)+'%2C'+(loc.lat+.008)+'&layer=mapnik&marker='+loc.lat+'%2C'+loc.lon;$('#customer-directions').href=$('#driver-directions').href}}
function startDriverMap(){const addr=[savedLocation.street,savedLocation.area,savedLocation.town].filter(Boolean).join(', ')||'14 Nomonde Street, Village, Eastern Cape, South Africa';$('#driver-directions').href='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(addr);const status=$('#driver-map-status');status.textContent='Requesting this device’s location…';if(!navigator.geolocation){status.textContent='Location services are not available in this preview.';return}if(driverLocationWatch!==null)return;driverLocationWatch=navigator.geolocation.watchPosition(pos=>{const {latitude:lat,longitude:lon}=pos.coords;const delta=.008;$('#driver-map').src='https://www.openstreetmap.org/export/embed.html?bbox='+(lon-delta)+'%2C'+(lat-delta)+'%2C'+(lon+delta)+'%2C'+(lat+delta)+'&layer=mapnik&marker='+lat+'%2C'+lon;status.textContent='Driver location updated · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});localStorage.setItem('kwa60-live-location',JSON.stringify({lat,lon,updatedAt:Date.now(),order:'KW60-014'}));renderCustomerTracking()},()=>{status.textContent='Allow location access to center the map.';driverLocationWatch=null},{enableHighAccuracy:true,timeout:12000,maximumAge:10000})}

const icons={home:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"/><path d="M3 10a2 2 0 0 1 .71-1.53l7-6a2 2 0 0 1 2.58 0l7 6A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>',products:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m11 21.73 2 0 7-4A2 2 0 0 0 21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73z"/><path d="M12 22V12M3.29 7 12 12l8.71-5M7.5 4.27l9 5.15"/></svg>',orders:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="4" x="8" y="2" rx="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2M12 11h4M12 16h4M8 11h.01M8 16h.01"/></svg>',profile:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="10" cy="7" r="4"/><path d="M8 15H7a4 4 0 0 0-4 4v2M16 13l1.2.6.7-1.3a1 1 0 0 1 1.9 0l.7 1.3 1.5.3a1 1 0 0 1 .5 1.7l-1.1 1 .3 1.6a1 1 0 0 1-1.5 1.1l-1.4-.7-1.4.7a1 1 0 0 1-1.5-1.1l.3-1.6-1.1-1a1 1 0 0 1 .5-1.7z"/></svg>',cart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/></svg>'};document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icons[el.dataset.icon]);
$('#detail-close').addEventListener('click',closeProduct);$('#product-overlay').addEventListener('click',e=>{if(e.target.id==='product-overlay')closeProduct()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeProduct();closeLocation()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open-product]')){e.preventDefault();openProduct(e.target.dataset.openProduct)}});
document.addEventListener('change',e=>{const pick=e.target.closest('[data-pick-item]');if(pick){driverChecks[pick.dataset.pickItem]=pick.checked;renderDriver()}});
document.addEventListener('click',e=>{const driverAction=e.target.closest('[data-driver-action]');if(driverAction){if(driverAction.dataset.driverAction==='accept'){driverOrder='picking';driverChecks={}}else if(driverAction.dataset.driverAction==='paid')driverOrder='paid';else if(driverAction.dataset.driverAction==='start')driverOrder='delivering';else{if(driverLocationWatch!==null&&navigator.geolocation){navigator.geolocation.clearWatch(driverLocationWatch);driverLocationWatch=null}driverOrder='delivered';driverDeliveries+=1;driverEarnings+=28;toast('Delivery completed · R28.00 earned')}renderDriver();return}const a=e.target.closest('[data-add]');if(a){e.preventDefault();e.stopPropagation();if(a.id==='detail-add'){add(a.dataset.add);closeProduct()}else add(a.dataset.add);return}const n=e.target.closest('[data-nav]');if(n){nav(n.dataset.nav);return}const c=e.target.closest('[data-category]');if(c){setCategory(c.dataset.category);return}const item=e.target.closest('[data-open-product]');if(item){openProduct(item.dataset.openProduct);return}const q=e.target.closest('[data-change]');if(q){const id=q.dataset.id;cart[id]=Math.max(0,(cart[id]||0)+Number(q.dataset.change));if(!cart[id])delete cart[id];save();return}const sh=e.target.closest('[data-shortcut]');if(sh){category=sh.dataset.shortcut==='Special Offers'?'All':'Personal Care';nav('Products');return}});
let addressMap=null,addressPin=null,currentLocationMarker=null,addressPinCoords=null;
function updateAddressPin(lat,lon){addressPinCoords={latitude:lat,longitude:lon};if(addressPin)addressPin.setLatLng([lat,lon]);else addressPin=L.circleMarker([lat,lon],{radius:9,color:'#710c17',weight:3,fillColor:'#c9001c',fillOpacity:1}).addTo(addressMap);$('#location-map-status').textContent='Delivery pin: '+lat.toFixed(5)+', '+lon.toFixed(5)+' · tap map to adjust';}
function locateAddress(){const status=$('#location-map-status');if(!navigator.geolocation){status.textContent='Location access is unavailable. You can still tap the map to place a pin.';return}status.textContent='Finding your current location…';navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;if(currentLocationMarker)currentLocationMarker.setLatLng([lat,lon]);else currentLocationMarker=L.circleMarker([lat,lon],{radius:7,color:'#fff',weight:3,fillColor:'#2583ee',fillOpacity:1}).addTo(addressMap).bindTooltip('Your current location');addressMap.setView([lat,lon],17);if(!addressPinCoords)updateAddressPin(lat,lon);else if(addressPin)addressPin.addTo(addressMap);status.textContent='Map centered on your current location. Tap to fine-tune the delivery pin.'},()=>{status.textContent='Could not get GPS. Allow location access, or tap the map to place your pin.';if(addressPinCoords){addressMap.setView([addressPinCoords.latitude,addressPinCoords.longitude],16)}else{addressMap.setView([-29,25],5)}},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
function initAddressMap(){if(typeof L==='undefined'){$('#location-map-status').textContent='Map is loading. Check your internet connection and try again.';return}if(!addressMap){addressMap=L.map('address-map',{zoomControl:true,scrollWheelZoom:false}).setView([-29,25],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(addressMap);addressMap.on('click',e=>updateAddressPin(e.latlng.lat,e.latlng.lng))}addressMap.invalidateSize();if(savedLocation.latitude&&savedLocation.longitude)updateAddressPin(Number(savedLocation.latitude),Number(savedLocation.longitude));locateAddress()}
function openLocation(){const l=$('#location-overlay');$('#location-street').value=savedLocation.street||'';$('#location-area').value=savedLocation.area||'';$('#location-town').value=savedLocation.town||'';$('#location-notes').value=savedLocation.notes||'';addressPinCoords=savedLocation.latitude&&savedLocation.longitude?{latitude:Number(savedLocation.latitude),longitude:Number(savedLocation.longitude)}:null;l.classList.add('open');l.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');setTimeout(()=>{initAddressMap();$('#location-street').focus()},180)}
function closeLocation(){const l=$('#location-overlay');l.classList.remove('open');l.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function updateAddressLabel(){const text=savedLocation.area?[savedLocation.area,savedLocation.town].filter(Boolean).join(', '):'KwaMakhi · Eastern Cape';document.querySelectorAll('[data-header-address]').forEach(label=>label.textContent=text)}
$('#location-open').addEventListener('click',openLocation);$('#locate-me').addEventListener('click',locateAddress);$('#location-close').addEventListener('click',closeLocation);$('#location-overlay').addEventListener('click',e=>{if(e.target.id==='location-overlay')closeLocation()});$('#location-form').addEventListener('submit',e=>{e.preventDefault();savedLocation={street:$('#location-street').value.trim(),area:$('#location-area').value.trim(),town:$('#location-town').value.trim(),notes:$('#location-notes').value.trim(),latitude:addressPinCoords?.latitude??null,longitude:addressPinCoords?.longitude??null};localStorage.setItem('kwa60-location',JSON.stringify(savedLocation));updateAddressLabel();$('#location-saved').textContent='Delivery address saved on this device.';setTimeout(closeLocation,650)});
for(const [id,key] of [['profile-name','name'],['profile-surname','surname'],['profile-email','email'],['profile-mobile','mobile'],['profile-id-type','idType'],['profile-id-number','idNumber']])if(savedProfile[key])$('#'+id).value=savedProfile[key];$('#profile-consent').checked=!!savedProfile.consent;
$('#profile-form').addEventListener('submit',e=>{e.preventDefault();savedProfile={name:$('#profile-name').value.trim(),surname:$('#profile-surname').value.trim(),email:$('#profile-email').value.trim(),mobile:$('#profile-mobile').value.trim(),idType:$('#profile-id-type').value,idNumber:$('#profile-id-number').value.trim(),consent:$('#profile-consent').checked};localStorage.setItem('kwa60-profile',JSON.stringify(savedProfile));$('#profile-saved').textContent='Your details have been saved on this device.';toast('Profile saved')});
$('#search').addEventListener('input',e=>{query=e.target.value;renderProducts()});$('#product-search').addEventListener('input',e=>{query=e.target.value;renderProducts()});$('#product-search').addEventListener('focus',()=>{if(query)renderProducts()});$('#clear-search').addEventListener('click',()=>{$('#search').value='';$('#product-search').value='';query='';renderProducts()});$('#back-categories').addEventListener('click',()=>{category='All';query='';$('#search').value='';$('#product-search').value='';renderProducts();$('#screen-products').scrollTop=0});$('#clear-cart').addEventListener('click',()=>{cart={};save()});$('#checkout').addEventListener('click',()=>{if(subtotal()<100)return;alert('Checkout will be enabled when Kwamakhi Store payment services are connected.')});$('#driver-toggle').addEventListener('click',()=>{driverOnline=!driverOnline;renderDriver()});
updateAddressLabel();renderHome();renderProducts();renderCart();renderDriver();renderCustomerTracking();const hash=location.hash.replace('#','');if(['Home','Products','Orders','Profile','Cart','Driver'].includes(hash))nav(hash);
